package com.simon.voiceime;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import android.text.Layout;import java.io.*;import java.util.*;import androidx.test.platform.app.InstrumentationRegistry;
/** X1-only integration scenarios. Host truth uses EditText Layout, never CursorAnchorInfo. */
public class App690ECorrectionAndroidTest extends junit.framework.TestCase {
 Instrumentation inst;Activity activity;EditText field;SimonIMEService service;File evidence;
 final Map<String,Object> prefsBefore=new HashMap<>();
 void main(Runnable work){inst.runOnMainSync(work);}
 @Override protected void setUp()throws Exception {
  inst=InstrumentationRegistry.getInstrumentation();evidence=new File(inst.getContext().getFilesDir(),"app690e-evidence");evidence.mkdirs();
  var prefs=inst.getTargetContext().getSharedPreferences("simon_ime_prefs",0);for(String name:new String[]{"dual_hand_enabled","dual_hand_mode","ime_auto_upload"})prefsBefore.put(name,prefs.getAll().get(name));
  prefs.edit().putBoolean("dual_hand_enabled",true).putBoolean("dual_hand_mode",false).putBoolean("ime_auto_upload",false).commit();
  activity=inst.startActivitySync(new Intent(inst.getContext(),DualHand689SandboxActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));
  main(()->{field=activity.findViewById(android.R.id.edit);field.requestFocus();((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(field,0);});
  long end=SystemClock.uptimeMillis()+5000;while(service==null&&SystemClock.uptimeMillis()<end){main(()->{try{Class<?> c=Class.forName("android.view.WindowManagerGlobal");Object wm=c.getDeclaredMethod("getInstance").invoke(null);var f=c.getDeclaredField("mViews");f.setAccessible(true);for(Object v:(List<?>)f.get(wm)){View view=(View)v;if(view.findViewById(R.id.voiceKeyboard)==null)continue;Context context=view.getContext();while(context instanceof ContextWrapper&&!(context instanceof SimonIMEService))context=((ContextWrapper)context).getBaseContext();if(context instanceof SimonIMEService)service=(SimonIMEService)context;}}catch(Exception e){throw new AssertionError(e);}});Thread.sleep(25);}assertNotNull("actual IME service window",service);
 }
 @Override protected void tearDown(){main(()->{if(activity!=null)activity.finish();});var edit=inst.getTargetContext().getSharedPreferences("simon_ime_prefs",0).edit();for(var e:prefsBefore.entrySet()){if(e.getValue()==null)edit.remove(e.getKey());else edit.putBoolean(e.getKey(),(Boolean)e.getValue());}edit.commit();}
 void page(String name)throws Exception {main(()->{try{var selected=SimonIMEService.class.getDeclaredField("dualHandSelected");selected.setAccessible(true);selected.setBoolean(service,name.equals("dual_hand"));Class<?> mode=Class.forName("com.simon.voiceime.SimonIMEService$KeyboardMode");var method=SimonIMEService.class.getDeclaredMethod("switchKeyboard",mode);method.setAccessible(true);method.invoke(service,Enum.valueOf((Class)mode,name.equals("voice")?"VOICE":"BOPOMOFO"));}catch(Exception e){throw new AssertionError(e);}});Thread.sleep(150);}
 Object editor()throws Exception {if(!((Boolean)read(service,"dualHandSelected")))return read(service,"pageCorrection");Object keyboard=read(service,"dualHandPage");return read(keyboard,"hooks");}
 Object read(Object object,String name)throws Exception {for(Class<?> c=object.getClass();c!=null;c=c.getSuperclass())try{var f=c.getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(NoSuchFieldException missing){}throw new NoSuchFieldException(name);}
 void screenshot(String name)throws Exception {Bitmap b=inst.getUiAutomation().takeScreenshot();assertNotNull(b);try(FileOutputStream out=new FileOutputStream(new File(evidence,name+".png"))){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}finally{b.recycle();}}
 void tap(View view)throws Exception {Rect bounds=new Rect();main(()->{int[] at=new int[2];view.getLocationOnScreen(at);bounds.set(at[0],at[1],at[0]+view.getWidth(),at[1]+view.getHeight());});long time=SystemClock.uptimeMillis();for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(time,SystemClock.uptimeMillis(),action,bounds.centerX(),bounds.centerY(),0);try{assertTrue(inst.getUiAutomation().injectInputEvent(e,true));}finally{e.recycle();}}inst.waitForIdleSync();}
 void flow(String name)throws Exception {flow(name,false);}
 void flow(String name,boolean top)throws Exception {
  page(name);if(top)main(()->{if(activity.getActionBar()!=null)activity.getActionBar().hide();FrameLayout.LayoutParams p=(FrameLayout.LayoutParams)field.getLayoutParams();p.gravity=Gravity.TOP;field.setLayoutParams(p);});main(()->{field.setText("銀行甲");field.setSelection(1);});Thread.sleep(300);main(()->field.setSelection(2));
  long end=SystemClock.uptimeMillis()+5000;Object c=null;TextView marker=null;while(SystemClock.uptimeMillis()<end){try{c=editor();}catch(Exception absent){}if(c!=null){marker=(TextView)read(c,"marker");if(marker!=null&&marker.getWidth()>0)break;}Thread.sleep(25);}assertNotNull(c);assertNotNull("capsule for committed character",marker);final Object correction=c;final TextView capsule=marker;
  final int[][] actual={null},expected={null};main(()->{Layout layout=field.getLayout();int[] at=new int[2];field.getLocationOnScreen(at);int line=layout.getLineForOffset(1);float left=at[0]+field.getTotalPaddingLeft()-field.getScrollX()+layout.getPrimaryHorizontal(1),glyphTop=at[1]+field.getTotalPaddingTop()-field.getScrollY()+layout.getLineTop(line),bottom=at[1]+field.getTotalPaddingTop()-field.getScrollY()+layout.getLineBottom(line);Rect visible=new Rect();field.getWindowVisibleDisplayFrame(visible);expected[0]=expectedPosition(left,glyphTop,bottom,capsule.getWidth(),capsule.getHeight(),field.getResources().getDisplayMetrics().widthPixels,visible.top,visible.bottom,field.getResources().getDisplayMetrics().density);int[] xy=new int[2];capsule.getLocationOnScreen(xy);actual[0]=xy;});float density=field.getResources().getDisplayMetrics().density;assertEquals(expected[0][0],actual[0][0],2*density);assertEquals(expected[0][1],actual[0][1],2*density);
  try(java.io.Writer out=new java.io.FileWriter(new File(evidence,name+"-position.json"))){out.write(new org.json.JSONObject().put("page",name).put("actual",new org.json.JSONArray(actual[0])).put("expected_layout",new org.json.JSONArray(expected[0])).put("density",density).toString());}
  screenshot(name+(top?"-top":"")+"-capsule");tap(capsule);Thread.sleep(200);PopupWindow grid=(PopupWindow)read(correction,"popup");assertNotNull("3x3 popup",grid);screenshot(name+(top?"-top":"")+"-grid");
  final TextView[] chosen={null};main(()->findChoice(grid.getContentView(),chosen));assertNotNull("different single-character choice",chosen[0]);String replacement=chosen[0].getText().toString();tap(chosen[0]);Thread.sleep(200);main(()->{assertEquals("銀"+replacement+"甲",field.getText().toString());assertEquals(2,field.getSelectionStart());assertEquals(2,field.getSelectionEnd());});screenshot(name+"-replaced");
 }
 void findChoice(View view,TextView[] chosen){if(chosen[0]!=null)return;if(view instanceof TextView){String text=((TextView)view).getText().toString();if(view.isEnabled()&&text.codePointCount(0,text.length())==1&&!text.equals("行")&&!text.isEmpty())chosen[0]=(TextView)view;}if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)findChoice(((ViewGroup)view).getChildAt(i),chosen);}
 static int[] expectedPosition(float left,float top,float bottom,int width,int height,int screen,int visibleTop,int visibleBottom,float density){
  // Same scenario can run on the 6.89.1 APK, where the new pure function is not packaged.
  try{Class<?> c=Class.forName("com.simon.voiceime.CorrectionPosition");var m=c.getDeclaredMethod("place",float.class,float.class,float.class,int.class,int.class,int.class,int.class,int.class,float.class);m.setAccessible(true);return (int[])m.invoke(null,left,top,bottom,width,height,screen,visibleTop,visibleBottom,density);}catch(ClassNotFoundException oldApk){int x=Math.max(0,Math.min(Math.round(left-width/2f),Math.max(0,screen-width))),above=(int)Math.ceil(top-height/2f-8*density),y=above>=visibleTop?above:(int)Math.floor(bottom+8*density-height/2f);return new int[]{x,Math.max(visibleTop,Math.min(y,visibleBottom-height))};}catch(Exception e){throw new AssertionError(e);}
 }
 java.lang.reflect.Method method(Object object,String name,Class<?>... args)throws Exception {for(Class<?> c=object.getClass();c!=null;c=c.getSuperclass())try{var m=c.getDeclaredMethod(name,args);m.setAccessible(true);return m;}catch(NoSuchMethodException missing){}throw new NoSuchMethodException(name);}
 Map<String,String> filesSnapshot(File dir)throws Exception {Map<String,String> result=new TreeMap<>();scanFiles(dir,dir,result);return result;}
 void scanFiles(File root,File dir,Map<String,String> result)throws Exception {File[] children=dir.listFiles();if(children==null)return;for(File f:children){if(f.isDirectory())scanFiles(root,f,result);else if(!f.getName().equals("dual_hand_personal.tsv")){byte[] bytes=java.nio.file.Files.readAllBytes(f.toPath());String hash=java.util.Base64.getEncoder().encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));result.put(root.toPath().relativize(f.toPath()).toString(),bytes.length+":"+hash);}}}
 public void testProtectedRecentRecordsHaveNoMainThreadDiskAccess()throws Exception {
  page("voice");main(()->field.setText("銀行"));Thread.sleep(500);Object correction=editor();assertNotNull(correction);
  for(int type:new int[]{129,145,18,1}){
   main(()->{field.setInputType(type);field.setImeOptions(type==1?android.view.inputmethod.EditorInfo.IME_FLAG_NO_PERSONALIZED_LEARNING:0);((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).restartInput(field);});Thread.sleep(500);main(()->assertTrue(service.dualHandProtected()));
   Map<String,String> before=filesSnapshot(inst.getTargetContext().getFilesDir());
   main(()->{StrictMode.ThreadPolicy previous=StrictMode.getThreadPolicy();StrictMode.setThreadPolicy(new StrictMode.ThreadPolicy.Builder().detectDiskReads().detectDiskWrites().penaltyDeath().build());try{method(correction,"recordCommit",String.class,List.class).invoke(correction,"銀行",Arrays.asList("ㄧㄣ","ㄏㄤ"));method(correction,"selection",int.class,int.class,int.class,int.class).invoke(correction,1,1,-1,-1);method(correction,"remember",List.class,String.class,long.class).invoke(correction,Collections.singletonList("ㄏㄤ"),"行",service.dualHandFieldGeneration());assertNull(read(correction,"marker"));assertTrue(((Map<?,?>)read(read(correction,"records"),"positions")).isEmpty());}catch(Exception e){throw new AssertionError(e);}finally{StrictMode.setThreadPolicy(previous);}});
   assertEquals(before,filesSnapshot(inst.getTargetContext().getFilesDir()));
  }
 }
 public void testDualHandTop()throws Exception {flow("dual_hand",true);}
 public void testVoiceTop()throws Exception {flow("voice",true);}
 public void testZhuyin41Top()throws Exception {flow("bopomofo",true);}
 public void testVoiceFlow()throws Exception {flow("voice");}
 public void testZhuyin41Flow()throws Exception {flow("bopomofo");}
 public void testDualHandFlow()throws Exception {flow("dual_hand");}
}
